mapper.select:
SELECT a.*, b.clazz_name, b.dept_id, c.dept_name, d.dorm_no, e.dorm_building_name FROM student a LEFT JOIN clazz b ON a.clazz_id = b.id LEFT JOIN dept c ON b.dept_id = c.id LEFT JOIN dorm d ON a.dorm_id = d.id LEFT JOIN dorm_building e ON d.dorm_building_id = e.id
b.dept_id = #{pageReq.deptId}
and a.clazz_id = #{pageReq.clazzId}
and a.student_no like concat('%', #{pageReq.studentNo}, '%')
and a.student_name like concat('%', #{pageReq.studentName}, '%')
and a.sex = #{pageReq.sex}
order by a.id desc
